 *
 * @private
 */
export class ImageId {
    name: string;
    iconsetId?: string;

    constructor(id: string | ImageId | ImageIdSpec) {
        if (typeof id === 'string') {
            this.name = id;
        } else {
            this.name = id.name;
            this.iconsetId = id.iconsetId;
        }
    }

