const border = 3;

import type {StyleGlyph} from './style_glyph';

export type GlyphData = {
    glyphs: Array<StyleGlyph>;
    ascender?: number;
    descender?: number;
};

function readFontstacks(pbf: PbfReader): GlyphData {
    const glyphData: GlyphData = {glyphs: []};
    let field: number;
    while ((field = pbf.nextField())) {
        if (field === 1) readFontstack(pbf, pbf.readVarint() + pbf.pos, glyphData);
    }
    return glyphData;
}

function readFontstack(pbf: PbfReader, end: number, glyphData: GlyphData) {
    let field: number;
    while ((field = pbf.nextField(end))) {
        if (field === 3) glyphData.glyphs.push(readGlyph(pbf, pbf.readVarint() + pbf.pos));
        else if (field === 4) glyphData.ascender = pbf.readSVarint();
        else if (field === 5) glyphData.descender = pbf.readSVarint();
    }
}

function readGlyph(pbf: PbfReader, end: number): StyleGlyph {
    let id = 0, width = 0, height = 0, left = 0, top = 0, advance = 0;
    let bitmap: Uint8Array;
    let field: number;
    while ((field = pbf.nextField(end))) {
        if (field === 1) id = pbf.readVarint();
        else if (field === 2) bitmap = pbf.readBytes();
        else if (field === 3) width = pbf.readVarint();
        else if (field === 4) height = pbf.readVarint();
        else if (field === 5) left = pbf.readSVarint();
        else if (field === 6) top = pbf.readSVarint();
        else if (field === 7) advance = pbf.readVarint();
    }
    return {
        id,
        bitmap: new AlphaImage({width: width + 2 * border, height: height + 2 * border}, bitmap),
        metrics: {width, height, left, top, advance}
    };
}

export default function parseGlyphPbf(data: ArrayBuffer | Uint8Array): GlyphData {
    return readFontstacks(new PbfReader(data));
}

export const GLYPH_PBF_BORDER = border;
/**
 * @typedef {Object} PotpackBox
 * @property {number} w Box width.
 * @property {number} h Box height.
 * @property {number} [x] X coordinate in the resulting container.
 * @property {number} [y] Y coordinate in the resulting container.
 */

/**
 * @typedef {Object} PotpackStats
 * @property {number} w Width of the resulting container.
 * @property {number} h Height of the resulting container.
 * @property {number} fill The space utilization value (0 to 1). Higher is better.
 */

/**
 * Packs 2D rectangles into a near-square container.
 *
 * Mutates the {@link boxes} array: it's sorted (by height/width),
 * and box objects are augmented with `x`, `y` coordinates.
 *
 * @param {PotpackBox[]} boxes
 * @return {PotpackStats}
 */
export default function potpack(boxes) {

    // calculate total box area and maximum box width
    let area = 0;
    let maxWidth = 0;

    for (const box of boxes) {
        area += box.w * box.h;
        maxWidth = Math.max(maxWidth, box.w);
    }

    // sort the boxes for insertion by height, descending
    boxes.sort((a, b) => b.h - a.h);

    // aim for a squarish resulting container,
    // slightly adjusted for sub-100% space utilization
    const startWidth = Math.max(Math.ceil(Math.sqrt(area / 0.95)), maxWidth);

    // start with a single empty space, unbounded at the bottom
    const spaces = [{x: 0, y: 0, w: startWidth, h: Infinity}];

    let width = 0;
    let height = 0;

    for (const box of boxes) {
        // look through spaces backwards so that we check smaller spaces first
        for (let i = spaces.length - 1; i >= 0; i--) {
            const space = spaces[i];

            // look for empty spaces that can accommodate the current box
            if (box.w > space.w || box.h > space.h) continue;

            // found the space; add the box to its top-left corner
            // |-------|-------|
            // |  box  |       |
            // |_______|       |
            // |         space |
            // |_______________|
            box.x = space.x;
            box.y = space.y;

            height = Math.max(height, box.y + box.h);
            width = Math.max(width, box.x + box.w);

            if (box.w === space.w && box.h === space.h) {
                // space matches the box exactly; remove it
                const last = spaces.pop();
                if (last && i < spaces.length) spaces[i] = last;

            } else if (box.h === space.h) {
                // space matches the box height; update it accordingly
                // |-------|---------------|
                // |  box  | updated space |
                // |_______|_______________|
                space.x += box.w;
                space.w -= box.w;

            } else if (box.w === space.w) {
                // space matches the box width; update it accordingly
                // |---------------|
                // |      box      |
                // |_______________|
                // | updated space |
                // |_______________|
                space.y += box.h;
                space.h -= box.h;

            } else {
                // otherwise the box splits the space into two spaces
                // |-------|-----------|
                // |  box  | new space |
                // |_______|___________|
                // | updated space     |
                // |___________________|
                spaces.push({
                    x: space.x + box.w,
                    y: space.y,
                    w: space.w - box.w,
                    h: box.h
                });
                space.y += box.h;
                space.h -= box.h;
            }
            break;
        }
    }

    return {
        w: width, // container width
        h: height, // container height
        fill: (area / (width * height)) || 0 // space utilization
    };
}
