    // OpenGL cubemap faces use a bottom-left origin; Metal uses top-left (see flipV in
    // render_sky_layer.cpp) so skip this flip when VIEWPORT_ORIGIN_TOP_LEFT is defined.
    v_position.y *= -1.0;
