void main() {
    float alpha = shapeCircle(v_uv);
    vec3 color = vec3(1.0, 1.0, 1.0);
    alpha *= v_intensity;
    glFragColor = vec4(color * alpha, alpha);

    HANDLE_WIREFRAME_DEBUG;
