const subclasses: Record<Exclude<TypedStyleLayer['type'], 'custom'>, TypedStyleLayerConstructor> = {
    circle,
    heatmap,
    hillshade,
    fill,
    'fill-extrusion': fillExtrusion,
    building,
    line,
    symbol,
    background,
    raster,
    'raster-particle': rasterParticle,
    sky,
