/**
 * Invokes the wrapped function in a non-blocking way when trigger() is called. Invocation requests
 * are ignored until the function was actually invoked.
 *
 * @private
 */
class ThrottledInvoker {
    _channel: MessageChannel | undefined;
    _triggered: boolean;
    _callback: () => void;

    constructor(callback: () => void) {
        this._callback = callback;
        this._triggered = false;
        if (typeof MessageChannel !== 'undefined') {
            this._channel = new MessageChannel();
            this._channel.port2.onmessage = () => {
                this._triggered = false;
                this._callback();
            };
        }
    }

    trigger() {
        if (!this._triggered) {
            this._triggered = true;
            if (this._channel) {
                this._channel.port1.postMessage(true);
            } else {
                setTimeout(() => {
                    this._triggered = false;
                    this._callback();
                }, 0);
            }
        }
    }

    remove() {
        if (this._channel) {
            this._channel.port1.close();
            this._channel.port2.close();
        }
        this._callback = () => {};
    }
}

export default ThrottledInvoker;
/**
 * Which render source partition this tile is parsed for.
 * Mirrors C++ RenderVectorSource splits in vector_source_factory.cpp.
 * Undefined/null = no filtering (single source, all layers).
 */
export const RenderSourceType = {
    Other: 0,
    Symbol: 1,
    FillExtrusion: 2,
    HdRoadCoverage: 3,
    HdRoadElevation: 4,
} as const;
export type RenderSourceType = typeof RenderSourceType[keyof typeof RenderSourceType];
import ThrottledInvoker from './throttled_invoker';
import {bindAll, isWorker} from './util';
import {PerformanceUtils} from './performance';
import {RenderSourceType} from '../source/render_source_type';

import type {Cancelable} from '../types/cancelable';

export type TaskMetadata = {
    type: 'message' | 'maybePrepare' | 'parseTile';
    renderSourceType?: RenderSourceType | null;
    zoom?: number;
};

type TaskFunction = () => void;

type Task = {
    fn: TaskFunction;
    metadata: TaskMetadata;
    priority: number;
    id: number;
};

class Scheduler {

    tasks: Map<number, Task>;
    invoker: ThrottledInvoker;
    nextId: number;

    constructor() {
        this.tasks = new Map();
        bindAll(['process'], this);
        this.invoker = new ThrottledInvoker(this.process);
        this.nextId = 0;
    }

    add(fn: TaskFunction, metadata: TaskMetadata): Cancelable | null {
        const id = this.nextId++;
        const priority = getPriority(metadata);

        if (priority === 0) {
            // Process tasks with priority 0 immediately. Do not yield to the event loop.
            const m = isWorker(self) ? PerformanceUtils.beginMeasure('workerTask') : undefined;
            try {
                fn();
            } finally {
                if (m) PerformanceUtils.endMeasure(m);
            }
            // Don't return an empty cancel because we can't actually be cancelled
            return null;
        }

        this.tasks.set(id, {fn, metadata, priority, id});
        this.invoker.trigger();
        return {
            cancel: () => {
                this.tasks.delete(id);
            }
        };
    }

    process() {
        const m = isWorker(self) ? PerformanceUtils.beginMeasure('workerTask') : undefined;
        try {
            const task = this.pick();
            if (!task) return;

            this.tasks.delete(task.id);
            // Schedule another process call if we know there's more to process _before_ invoking the
            // current task. This is necessary so that processing continues even if the current task
            // doesn't execute successfully.
            if (this.tasks.size > 0) {
                this.invoker.trigger();
            }

            task.fn();
        } finally {
            if (m) PerformanceUtils.endMeasure(m);
        }
    }

    pick(): Task | null {
        let result: Task | null = null;
        let minPriority = Infinity;
        for (const task of this.tasks.values()) {
            if (task.priority < minPriority) {
                minPriority = task.priority;
                result = task;
            }
        }
        return result;
    }

    remove() {
        this.tasks.clear();
        this.invoker.remove();
    }
}

function getPriority({type, renderSourceType, zoom}: TaskMetadata): number {
    zoom = zoom || 0;
    const isSymbol = renderSourceType === RenderSourceType.Symbol;
    if (type === 'message') return 0;
    if (type === 'maybePrepare' && !isSymbol) return 100 - zoom;
    if (type === 'parseTile' && !isSymbol) return 200 - zoom;
    if (type === 'parseTile' && isSymbol) return 300 - zoom;
    if (type === 'maybePrepare' && isSymbol) return 400 - zoom;
    return 500;
}

export default Scheduler;
import Scheduler from './scheduler';
import assert from '../style-spec/util/assert';
import {bindAll, isWorker} from './util';
import {serialize, deserialize} from './web_worker_transfer';

import type {Serialized} from './web_worker_transfer';
import type {Transferable} from '../types/transferable';
import type {TaskMetadata} from './scheduler';
import type {WorkerSource, WorkerSourceRequest, WorkerSourceType} from '../source/worker_source';
import type {ActorMessage, ActorInbox} from './actor_messages';

export type Task = {
    type: ActorMessage | '<response>';
    id?: string;
    data?: Serialized;
    error?: Serialized;
    targetMapId?: number;
    sourceMapId?: number;
};

type PendingResponse = {
    resolve: (value: unknown) => void;
    reject: (err: Error) => void;
    metadata: TaskMetadata;
    detach?: () => void;
};

const DEFAULT_METADATA: TaskMetadata = {type: 'message'};

/**
 * Constraint that lets {@link Actor#send} index `Outbox[T]` generically.
 * @private
 */
type MessageMap = {[type: string]: {params: unknown; result: unknown}};

/**
 * Dispatch-table view of the parent used by {@link Actor#processTask}: handlers
 * keyed by message name, plus `getWorkerSource` for dynamic `sourcetype.method`
 * messages. Each handler returns its result (or a Promise of it); `processTask`
 * awaits and posts a single `<response>`.
 * @private
 */
type ActorParent = {
    [K in keyof ActorInbox]: (mapId: number, params: unknown) => unknown;
} & {
    getWorkerSource?: (mapId: number, params: WorkerSourceRequest) => WorkerSource;
};

/**
 * An implementation of the [Actor design pattern](http://en.wikipedia.org/wiki/Actor_model)
 * that maintains the relationship between asynchronous tasks and the objects
 * that spin them off - in this case, tasks like parsing parts of styles,
 * owned by the styles
 *
 * `Outbox` is the inbox this actor sends to: a worker-side actor (parent
 * {@link MapWorker}) is an `Actor<MainInbox>`; a main-side actor (parent
 * {@link Style}) is an `Actor<WorkerInbox>`.
 *
 * @param {WebWorker} target
 * @param {unknown} parent
 * @param {number} [mapId] A unique identifier for the Map instance using this Actor.
 * @private
 */
class Actor<Outbox extends MessageMap> {
    target: Worker;
    parent: ActorParent;
    name?: string;
    mapId?: number;
    pendingResponses: Map<string, PendingResponse>;
    scheduler: Scheduler;

    constructor(target: Worker, parent: unknown, mapId?: number) {
        this.target = target;
        this.parent = parent as ActorParent;
        this.mapId = mapId;
        this.pendingResponses = new Map();
        bindAll(['receive'], this);
        this.target.addEventListener('message', this.receive, false);
        this.scheduler = new Scheduler();
    }

    /**
     * Sends a message from a main-thread map to a Worker or from a Worker back to a
     * main-thread map instance, and resolves with the worker's result. Registers a pending
     * response and is cancelable via `signal`. Use {@link Actor#notify} if you don't need a response.
     *
     * @param type The name of the target method to invoke or '[source-type].[source-name].name' for a method on a WorkerSource.
     * @param data The message payload.
     * @param options Optional send options (`signal` to cancel, `targetMapId`, scheduler `metadata`).
     * @private
     */
    send<T extends keyof Outbox>(type: T, data: Outbox[T]['params'], options?: {signal?: AbortSignal; targetMapId?: number; metadata?: TaskMetadata}): Promise<Outbox[T]['result']> {
        const {signal, targetMapId, metadata} = options || {};
        // We're using a string ID instead of numbers because they are being used as object keys
        // anyway, and thus stringified implicitly. We use random IDs because an actor may receive
        // message from multiple other actors which could run in different execution context. A
        // linearly increasing ID could produce collisions.
        const id = Math.round((Math.random() * 1e18)).toString(36).substring(0, 10);
        const buffers: Set<Transferable> = new Set();

        if (signal && signal.aborted) {
            return Promise.reject(signal.reason as Error);
        }

        this.target.postMessage({
            id,
            type: type as ActorMessage,
            targetMapId,
            sourceMapId: this.mapId,
            data: serialize(data, buffers)
        }, [...buffers]);

        return new Promise((resolve, reject) => {
            const entry: PendingResponse = {resolve, reject, metadata: metadata || DEFAULT_METADATA};

            if (signal) {
                const abortHandler = () => {
                    this.pendingResponses.delete(id);
                    reject(signal.reason as Error);
                };
                signal.addEventListener('abort', abortHandler, {once: true});
                entry.detach = () => signal.removeEventListener('abort', abortHandler);
            }

            this.pendingResponses.set(id, entry);
        });
    }

    /**
     * Sends a message without awaiting for response. Use {@link Actor#send} if you need to await a response.
     * @private
     */
    notify<T extends keyof Outbox>(type: T, data: Outbox[T]['params'], options?: {targetMapId?: number}): void {
        const {targetMapId} = options || {};
        const buffers: Set<Transferable> = new Set();

        this.target.postMessage({
            type: type as ActorMessage,
            targetMapId,
            sourceMapId: this.mapId,
            data: serialize(data, buffers)
        }, [...buffers]);
    }

    /**
     * Convenience wrapper around {@link send} for the common callback + cancellation pattern:
     * fires the message with a fresh AbortController, routes the result to a node-style callback,
     * swallows AbortError, and returns the {@link AbortController} so the caller can abort the request.
     *
     * @private
     */
    sendCancelable<T extends keyof Outbox>(
        type: T,
        data: Outbox[T]['params'],
        options: {targetMapId?: number; metadata?: TaskMetadata},
        callback: (err?: Error | null, result?: Outbox[T]['result']) => void
    ): AbortController {
        const controller = new AbortController();
        this.send(type, data, {...options, signal: controller.signal})
            .then((result) => callback(null, result))
            .catch((err: Error) => { if (err.name !== 'AbortError') callback(err); });
        return controller;
    }

    /**
     * A send-only view bound to `mapId`, for {@link WorkerSource}s. One worker-side
     * actor serves many maps and has no `mapId` of its own, so its outbound messages
     * must carry the owning map's id as `targetMapId`.
     * @private
     */
    getWorkerSourceActor(mapId: number): Pick<Actor<Outbox>, 'send' | 'notify' | 'sendCancelable' | 'scheduler'> {
        return {
            scheduler: this.scheduler,
            send: <T extends keyof Outbox>(type: T, data: Outbox[T]['params'], options?: {signal?: AbortSignal; metadata?: TaskMetadata}) => {
                return this.send(type, data, {...options, targetMapId: mapId});
            },
            notify: <T extends keyof Outbox>(type: T, data: Outbox[T]['params']) => {
                this.notify(type, data, {targetMapId: mapId});
            },
            sendCancelable: <T extends keyof Outbox>(type: T, data: Outbox[T]['params'], options: {metadata?: TaskMetadata}, callback: (err?: Error | null, result?: Outbox[T]['result']) => void) => {
                return this.sendCancelable(type, data, {...options, targetMapId: mapId}, callback);
            },
        };
    }

    receive(message: MessageEvent<Task>) {
        const data = message.data;
        if (!data) return;

        const id = data.id;
        if (data.targetMapId && this.mapId !== data.targetMapId) {
            return;
        }

        if (isWorker(self)) {
            // Worker tasks go through the scheduler so they run in priority order and yield between
            // each other instead of blocking the message loop. The worker's own glyph/image responses
            // carry 'maybePrepare' metadata (from `metadata` on the originating `send`), deferring them
            // onto the shared scheduler ahead of tile parsing.
            const entry = this.pendingResponses.get(id);
            const metadata = (entry && entry.metadata) || DEFAULT_METADATA;
            this.scheduler.add(() => {
                // eslint-disable-next-line @typescript-eslint/no-floating-promises
                this.processTask(id, data);
            }, metadata);
        } else {
            // In the main thread, process messages immediately so that other work does not slip in
            // between getting partial data back from workers.
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.processTask(id, data);
        }
    }

    async processTask(id: string, task: Task): Promise<void> {
        if (task.type === '<response>') {
            // The handler has resolved, and we are now resolving or rejecting
            // the Promise in the originating actor, if there is one.
            const entry = this.pendingResponses.get(id);
            this.pendingResponses.delete(id);
            if (entry) {
                // If we get a response, but don't have a stored resolver, the request was canceled.
                if (entry.detach) entry.detach();
                // Deserialization can throw on a malformed payload; reject so the caller observes an
                // error instead of hanging on a Promise that never settles.
                try {
                    if (task.error) {
                        entry.reject(deserialize(task.error) as Error);
                    } else {
                        entry.resolve(deserialize(task.data));
                    }
                } catch (err) {
                    entry.reject(err as Error);
                }
            }

            return;
        }

        const buffers: Set<Transferable> = new Set();
        const params = deserialize(task.data);

        // `task.type` is either a MapWorker method name ('loadTile', etc.) or
        // `<sourcetype>.<method>` addressing a WorkerSource method directly (only
        // the `geojson.*` messages use this). Dispatch is by string either way.
        try {
            let result: unknown;
            if (this.parent[task.type]) {
                // task.type == 'loadTile', 'removeTile', etc.
                result = await this.parent[task.type](task.sourceMapId, params);
            } else if (this.parent.getWorkerSource) {
                // task.type == sourcetype.method
                const keys = task.type.split('.');
                const {source, scope} = params as {source: string; scope: string};
                const workerSource = this.parent.getWorkerSource(task.sourceMapId, {type: keys[0] as WorkerSourceType, source, scope});
                // eslint-disable-next-line @typescript-eslint/no-unsafe-call
                result = await workerSource[keys[1]](params);
            } else {
                throw new Error(`Could not find function ${task.type}`);
            }

            if (!id) return;

            this.target.postMessage({
                id,
                type: '<response>',
                sourceMapId: this.mapId,
                error: null,
                data: serialize(result, buffers)
            }, [...buffers]);
        } catch (err) {
            if (!id) assert(false, `"${task.type}" threw: ${(err as Error).message}`);

            this.target.postMessage({
                id,
                type: '<response>',
                sourceMapId: this.mapId,
                error: serialize(err),
                data: null
            }, []);
        }
    }

    remove() {
        // Reject any in-flight requests so their awaiters unwind instead of hanging forever once the
        // message listener is detached and responses can no longer arrive.
        for (const entry of this.pendingResponses.values()) {
            if (entry.detach) entry.detach();
            entry.reject(new DOMException('Actor removed', 'AbortError'));
        }
        this.pendingResponses.clear();
        this.scheduler.remove();
        this.target.removeEventListener('message', this.receive, false);
    }
}

export default Actor;
import config from '../util/config';
import browser from '../util/browser';
import {getURLExtension} from '../util/url';
import {processTileJSON as parseTileJson} from './load_tilejson';

import type {TileJSON} from '../types/tilejson';
import type {RequestManager} from '../util/mapbox';
import type {RequestParameters} from '../util/ajax';
import type {SourceSpecification} from '../style-spec/types';
import type {Options as TileJsonParserOptions} from './load_tilejson';

/**
 * Response returned by {@link TileProvider.loadTile}.
 *
 * Raster and raster-dem sources accept `data: ArrayBuffer | ImageBitmap`. Vector
 * sources require `ArrayBuffer` and will reject `ImageBitmap` responses at runtime
 * with an error.
 *
 * Providers that hand DEM sources a pre-decoded `ImageBitmap` should construct it
 * with `createImageBitmap(blob, {premultiplyAlpha: 'none', colorSpaceConversion: 'none'})`
 * so the canvas round-trip preserves elevation byte fidelity.
 *
 * @property {T} data - The raw tile payload.
 * @property {string} [expires] - Expires header value for tile caching.
 * @property {string} [cacheControl] - Cache-Control header value for tile caching.
 * @experimental This API is experimental and subject to change in future versions.
 * @private
 */
export type TileDataResponse<T> = {
    data: T;
    expires?: string;
    cacheControl?: string;
};

/**
 * Interface for a custom tile provider. Register a module URL with
 * {@link addTileProvider}, then reference it via `provider` in a source spec.
 * The module must default-export a class implementing this interface.
 *
 * Provider runs on the main thread for raster sources, in a Web Worker for
 * vector and raster-dem. Restrict to APIs available in both contexts (see
 * [worker-safe APIs](https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API/Functions_and_classes_available_to_workers))
 * for portability across source types.
 * @experimental This API is experimental and subject to change in future versions.
 * @private
 *
 * @example
 * import type {RequestParameters, TileDataResponse, TileProvider, TileJSON, RasterSourceSpecification} from 'mapbox-gl';
 *
 * export default class MyTileProvider implements TileProvider<ArrayBuffer> {
 *     private url: string;
 *
 *     constructor(options: RasterSourceSpecification) {
 *         this.url = options.url;
 *     }
 *
 *     async load(): Promise<Partial<TileJSON>> {
 *         const response = await fetch(this.url);
 *         return await response.json();
 *     }
 *
 *     async loadTile(tile: {z: number; x: number; y: number}, options: {request: RequestParameters; signal: AbortSignal}): Promise<TileDataResponse<ArrayBuffer>> {
 *         const response = await fetch(options.request.url, {signal: options.signal});
 *         return {data: await response.arrayBuffer()};
 *     }
 * }
 *
 * @example
 * import type {RequestParameters, TileDataResponse, TileProvider} from 'mapbox-gl';
 *
 * export default class MyBitmapTileProvider implements TileProvider<ImageBitmap> {
 *     async loadTile(tile: {z: number; x: number; y: number}, options: {request: RequestParameters; signal: AbortSignal}): Promise<TileDataResponse<ImageBitmap>> {
 *         const response = await fetch(options.request.url, {signal: options.signal});
 *         const blob = await response.blob();
 *         return {data: await createImageBitmap(blob)};
 *     }
 * }
 */
export interface TileProvider<T> {
    /**
     * Returns TileJSON metadata for the source. Called once during initialization
     * when the source has a `url` but no explicit `tiles`.
     *
     * @param options - Load options.
     * @param options.request - {@link RequestParameters} for the request.
     */
    load?: (options: {request: RequestParameters}) => Promise<Partial<TileJSON>>;

    /**
     * Fetches raw tile data.
     *
     * @param {{ z: number, x: number, y: number }} tile Tile coordinates.
     * @param {Object} options Load options.
     * @param options.request - {@link RequestParameters} for the request.
     * @param options.signal - Abort signal for cancellation.
     * @returns {TileDataResponse | null | undefined} Tile data to render.
     * Return `{data: null}` for an intentionally empty tile.
     * Return nullish to overscale the parent tile.
     */
    loadTile: (tile: {z: number; x: number; y: number}, options: {request: RequestParameters; signal: AbortSignal}) => Promise<TileDataResponse<T | null> | null | undefined>;
}

export type TileProviderConstructor = new (options: Partial<SourceSpecification>) => TileProvider<ArrayBuffer | ImageBitmap>;

/**
 * Registers a tile provider module URL by name. Call this **before** creating
 * the {@link Map} or adding sources that reference the provider. Re-registering
 * a name overwrites the previous URL but won't affect already-loaded workers.
 *
 * @param name - Provider name (e.g. `'pmtiles'`).
 * @param url - URL to an ES module that default-exports a {@link TileProvider} class.
 * @experimental This API is experimental and subject to change in future versions.
 * @private
 */
export function addTileProvider(name: string, url: string): void {
    if (!name || !url) {
        throw new Error('TileProvider name and URL are required');
    }

    config.TILE_PROVIDER_URLS[name] = browser.resolveURL(url);
}

const pendingLoads: Map<string, Promise<TileProviderConstructor>> = new Map();
const tileProviders: Map<string, TileProviderConstructor> = new Map();

/**
 * Dynamically imports a provider module and caches its class.
 * Deduplicates concurrent imports for the same provider.
 * On failure the pending entry is cleared so the next call retries —
 * a transient network error should not permanently poison the cache.
 * @private
 */
export async function loadTileProvider(name: string, url: string): Promise<TileProviderConstructor> {
    const cached = tileProviders.get(name);
    if (cached) return cached;

    const pending = pendingLoads.get(name);
    if (pending !== undefined) return pending;

    const load = import(/* webpackIgnore: true */ /* @vite-ignore */ url)
        .catch((err) => {
            throw new Error(`TileProvider "${name}" failed to load: ${err instanceof Error ? err.message : String(err)}`);
        })
        .then((mod: {default?: TileProviderConstructor}) => {
            const TileProviderClass = mod.default;
            if (typeof TileProviderClass !== 'function') {
                throw new Error(`TileProvider "${name}" module must default-export a class`);
            }
            // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
            if (typeof TileProviderClass.prototype.loadTile !== 'function') {
                throw new Error(`TileProvider "${name}" class must have a loadTile method`);
            }
            tileProviders.set(name, TileProviderClass);
            return TileProviderClass;
        })
        .finally(() => {
            pendingLoads.delete(name);
        });

    pendingLoads.set(name, load);
    return load;
}

/**
 * Resolves a tile provider by explicit name or by auto-detecting from a source URL extension.
 * Returns the provider name and resolved module URL, null if no provider applies, or an Error
 * when a provider was matched but its URL is invalid.
 *
 * @private
 */
export function resolveTileProvider(options: SourceSpecification & {provider?: string | false}): {name: string; url: string} | Error | null {
    if ('provider' in options && !options.provider) return null;

    let name = options.provider;
    if (!name && 'url' in options && options.url) {
        name = getURLExtension(options.url);
    }

    if (!name) return null;

    const rawUrl = config.TILE_PROVIDER_URLS[name];
    if (!rawUrl) return null;

    let url: string;
    try {
        url = new URL(rawUrl, config.API_URL).href;
    } catch (e) {
        return new Error(`TileProvider "${name}" has an invalid URL: "${rawUrl}"`);
    }

    return {name, url};
}

/**
 * Builds a TileJSON result from provider-returned metadata or falls back to
 * `options.tiles`. Returns an Error when neither source is available.
 * @private
 */
export function processTileJSON(options: TileJsonParserOptions, tileJSON: Partial<TileJSON> | null | undefined, requestManager: RequestManager): TileJSON | Error {
    if (tileJSON) {
        return parseTileJson(options, tileJSON, requestManager);
    }

    if (options.tiles && options.tiles.length > 0) {
        return {tiles: options.tiles} as TileJSON;
    }

    return new Error(`TileJSON is missing required "tiles" property`);
}
import {vec3} from 'gl-matrix';
import {number as interpolate} from '../style-spec/util/interpolate';
import {clamp} from '../util/util';

import type DEMData from './dem_data';

class MipLevel {
    size: number;
    minimums: Array<number>;
    maximums: Array<number>;
    leaves: Array<number>;

    constructor(size_: number) {
        this.size = size_;
        this.minimums = [];
        this.maximums = [];
        this.leaves = [];
    }

    getElevation(x: number, y: number): {
        min: number;
        max: number;
    } {
        const idx = this.toIdx(x, y);
        return {
            min: this.minimums[idx],
            max: this.maximums[idx]
        };
    }

    isLeaf(x: number, y: number): number {
        return this.leaves[this.toIdx(x, y)];
    }

    toIdx(x: number, y: number): number {
        return y * this.size + x;
    }
}

function aabbRayIntersect(min: vec3, max: vec3, pos: vec3, dir: vec3): number | null | undefined {
    let tMin = 0;
    let tMax = Number.MAX_VALUE;

    const epsilon = 1e-15;

    for (let i = 0; i < 3; i++) {
        if (Math.abs(dir[i]) < epsilon) {
            // Parallel ray
            if (pos[i] < min[i] || pos[i] > max[i])
                return null;
        } else {
            const ood = 1.0 / dir[i];
            let t1 = (min[i] - pos[i]) * ood;
            let t2 = (max[i] - pos[i]) * ood;
            if (t1 > t2) {
                const temp = t1;
                t1 = t2;
                t2 = temp;
            }
            if (t1 > tMin)
                tMin = t1;
            if (t2 < tMax)
                tMax = t2;
            if (tMin > tMax)
                return null;
        }
    }

    return tMin;
}

function triangleRayIntersect(
    ax: number,
    ay: number,
    az: number,
    bx: number,
    by: number,
    bz: number,
    cx: number,
    cy: number,
    cz: number,
    pos: vec3,
    dir: vec3,
): number | null | undefined {
    // Compute barycentric coordinates u and v to find the intersection
    const abX = bx - ax;
    const abY = by - ay;
    const abZ = bz - az;

    const acX = cx - ax;
    const acY = cy - ay;
    const acZ = cz - az;

    // pvec = cross(dir, a), det = dot(ab, pvec)
    const pvecX = dir[1] * acZ - dir[2] * acY;
    const pvecY = dir[2] * acX - dir[0] * acZ;
    const pvecZ = dir[0] * acY - dir[1] * acX;
    const det = abX * pvecX + abY * pvecY + abZ * pvecZ;

    if (Math.abs(det) < 1e-15)
        return null;

    const invDet = 1.0 / det;
    const tvecX = pos[0] - ax;
    const tvecY = pos[1] - ay;
    const tvecZ = pos[2] - az;
    const u = (tvecX * pvecX + tvecY * pvecY + tvecZ * pvecZ) * invDet;

    if (u < 0.0 || u > 1.0)
        return null;

    // qvec = cross(tvec, ab)
    const qvecX = tvecY * abZ - tvecZ * abY;
    const qvecY = tvecZ * abX - tvecX * abZ;
    const qvecZ = tvecX * abY - tvecY * abX;
    const v = (dir[0] * qvecX + dir[1] * qvecY + dir[2] * qvecZ) * invDet;

    if (v < 0.0 || u + v > 1.0)
        return null;

    return (acX * qvecX + acY * qvecY + acZ * qvecZ) * invDet;
}

function decodeBounds(x: number, y: number, depth: number, boundsMinx: number, boundsMiny: number, boundsMaxx: number, boundsMaxy: number, outMin: Array<number>, outMax: Array<number>) {
    const scale = 1 << depth;
    const rangex = boundsMaxx - boundsMinx;
    const rangey = boundsMaxy - boundsMiny;

    const minX = (x + 0) / scale * rangex + boundsMinx;
    const maxX = (x + 1) / scale * rangex + boundsMinx;
    const minY = (y + 0) / scale * rangey + boundsMiny;
    const maxY = (y + 1) / scale * rangey + boundsMiny;

    outMin[0] = minX;
    outMin[1] = minY;
    outMax[0] = maxX;
    outMax[1] = maxY;
}

// A small padding value is used with bounding boxes to extend the bottom below sea level
const aabbSkirtPadding = 100;

// A sparse min max quad tree for performing accelerated queries against dem elevation data.
// Each tree node stores the minimum and maximum elevation of its children nodes and a flag whether the node is a leaf.
// Node data is stored in non-interleaved arrays where the root is at index 0.
export default class DemMinMaxQuadTree {
    maximums: Array<number>;
    minimums: Array<number>;
    leaves: Array<number>;
    childOffsets: Array<number>;
    nodeCount: number;
    dem: DEMData;
    _siblingOffset: Array<Array<number>>;

    constructor(dem_: DEMData) {
        this.maximums = [];
        this.minimums = [];
        this.leaves = [];
        this.childOffsets = [];
        this.nodeCount = 0;
        this.dem = dem_;

        // Precompute the order of 4 sibling nodes in the memory. Top-left, top-right, bottom-left, bottom-right
        this._siblingOffset = [
            [0, 0],
            [1, 0],
            [0, 1],
            [1, 1]
        ];

        if (!this.dem)
            return;

        const mips = buildDemMipmap(this.dem);
        const maxLvl = mips.length - 1;

        // Create the root node
        const rootMip = mips[maxLvl];
        const min = rootMip.minimums;
        const max = rootMip.maximums;
        const leaves = rootMip.leaves;
        this._addNode(min[0], max[0], leaves[0]);

        // Construct the rest of the tree recursively
        this._construct(mips, 0, 0, maxLvl, 0);
    }

    // Performs raycast against the tree root only. Min and max coordinates defines the size of the root node
    raycastRoot(
        minx: number,
        miny: number,
        maxx: number,
        maxy: number,
        p: vec3,
        d: vec3,
        exaggeration: number = 1,
    ): number | null | undefined {
        const min: [number, number, number] = [minx, miny, -aabbSkirtPadding];
        const max: [number, number, number] = [maxx, maxy, this.maximums[0] * exaggeration];
        return aabbRayIntersect(min, max, p, d);
    }

    raycast(
        rootMinx: number,
        rootMiny: number,
        rootMaxx: number,
        rootMaxy: number,
        p: vec3,
        d: vec3,
        exaggeration: number = 1,
    ): number | null | undefined {
        if (!this.nodeCount)
            return null;

        const t = this.raycastRoot(rootMinx, rootMiny, rootMaxx, rootMaxy, p, d, exaggeration);
        if (t == null)
            return null;

        const tHits: number[] = [];
        const sortedHits: number[] = [];
        const boundsMin: number[] = [];
        const boundsMax: number[] = [];

        const stack = [{
            idx: 0,
            t,
            nodex: 0,
            nodey: 0,
            depth: 0
        }];

        // Traverse the tree until something is hit or the ray escapes
        while (stack.length > 0) {
            const {idx, t, nodex, nodey, depth} = stack.pop();

            if (this.leaves[idx]) {
                // DDA over the leaf's DEM texels using the '/' diagonal (matching the terrain shader).
                // Accurate because buildDemMipmap mip-0 now stores true texel max, so tEnter = t
                // is the correct AABB entry point. Uses edge-sharing and a height-based skip.
                decodeBounds(nodex, nodey, depth, rootMinx, rootMiny, rootMaxx, rootMaxy, boundsMin, boundsMax);

                const scale = 1 << depth;
                const minxUv = nodex / scale;
                const maxxUv = (nodex + 1) / scale;
                const minyUv = nodey / scale;
                const maxyUv = (nodey + 1) / scale;

                const {dim: demSz, floatView: fv, stride: st} = this.dem;
                const txMin = Math.floor(minxUv * demSz);
                const txMax = Math.ceil(maxxUv * demSz);
                const tyMin = Math.floor(minyUv * demSz);
                const tyMax = Math.ceil(maxyUv * demSz);
                const txCount = txMax - txMin;
                const tyCount = tyMax - tyMin;
                if (txCount <= 0 || tyCount <= 0) continue;

                const x0 = boundsMin[0];
                const y0 = boundsMin[1];
                const cellW = (boundsMax[0] - x0) / txCount;
                const cellH = (boundsMax[1] - y0) / tyCount;

                // Starting point on the ray (clamped to tile entry)
                const tEnter = Math.max(0, t);
                const entryX = p[0] + d[0] * tEnter;
                const entryY = p[1] + d[1] * tEnter;

                // Step direction
                const hasX = Math.abs(d[0]) > 1e-10;
                const hasY = Math.abs(d[1]) > 1e-10;
                const stepI = d[0] >= 0 ? 1 : -1;
                const stepJ = d[1] >= 0 ? 1 : -1;

                let ci = Math.max(0, Math.min(txCount - 1, Math.floor((entryX - x0) / cellW)));
                let cj = Math.max(0, Math.min(tyCount - 1, Math.floor((entryY - y0) / cellH)));

                // Distance along ray to cross one cell
                const tDeltaI = hasX ? Math.abs(cellW / d[0]) : Number.MAX_VALUE;
                const tDeltaJ = hasY ? Math.abs(cellH / d[1]) : Number.MAX_VALUE;
                // Distance to next cell boundary
                let tNextI = hasX ? tEnter + (x0 + (d[0] >= 0 ? ci + 1 : ci) * cellW - entryX) / d[0] : Number.MAX_VALUE;
                let tNextJ = hasY ? tEnter + (y0 + (d[1] >= 0 ? cj + 1 : cj) * cellH - entryY) / d[1] : Number.MAX_VALUE;

                const elev = (tx: number, ty: number) => fv[(ty + 1) * st + tx + 1] * exaggeration;
                let e00 = elev(txMin + ci,     tyMin + cj);
                let e10 = elev(txMin + ci + 1, tyMin + cj);
                let e01 = elev(txMin + ci,     tyMin + cj + 1);
                let e11 = elev(txMin + ci + 1, tyMin + cj + 1);

                let closestT: number | null = null;

                // Traverse cells in order along the ray
                for (let step = 0; step < txCount + tyCount; step++) {
                    const tExit = Math.min(tNextI, tNextJ);

                    // Height-based skip: for a downward ray, tExit is the lowest z the ray reaches in this cell
                    if (d[2] >= 0 || p[2] + d[2] * tExit <= Math.max(e00, e10, e01, e11)) {
                        const cx0 = x0 + ci * cellW;
                        const cx1 = cx0 + cellW;
                        const cy0 = y0 + cj * cellH;
                        const cy1 = cy0 + cellH;
                        // Triangle 1: (1,0) -> (0,0) -> (0,1)
                        const t0 = triangleRayIntersect(cx1, cy0, e10, cx0, cy0, e00, cx0, cy1, e01, p, d);
                        // Triangle 2: (0,1) -> (1,1) -> (1,0)
                        const t1 = triangleRayIntersect(cx0, cy1, e01, cx1, cy1, e11, cx1, cy0, e10, p, d);
                        if (t0 != null && t0 >= 0 && (closestT === null || t0 < closestT)) closestT = t0;
                        if (t1 != null && t1 >= 0 && (closestT === null || t1 < closestT)) closestT = t1;
                    }

                    // Move to next cell
                    const steppedI = tNextI < tNextJ;
                    if (steppedI) { ci += stepI; tNextI += tDeltaI; } else { cj += stepJ; tNextJ += tDeltaJ; }

                    // Check if we've exited the grid
                    if (ci < 0 || ci >= txCount || cj < 0 || cj >= tyCount) break;
                    // Early termination: found a hit and the ray has passed it in XY
                    if (closestT !== null && tExit > closestT) break;

                    // Update shared edges (reuse 2 corners, fetch 2 new ones)
                    if (steppedI) {
                        if (stepI > 0) { e00 = e10; e01 = e11; e10 = elev(txMin + ci + 1, tyMin + cj); e11 = elev(txMin + ci + 1, tyMin + cj + 1); } else { e10 = e00; e11 = e01; e00 = elev(txMin + ci, tyMin + cj); e01 = elev(txMin + ci, tyMin + cj + 1); }
                    } else {
                        if (stepJ > 0) { e00 = e01; e10 = e11; e01 = elev(txMin + ci, tyMin + cj + 1); e11 = elev(txMin + ci + 1, tyMin + cj + 1); } else { e01 = e00; e11 = e10; e00 = elev(txMin + ci, tyMin + cj); e10 = elev(txMin + ci + 1, tyMin + cj); }
                    }
                }

                if (closestT !== null) return closestT || 0; // normalize -0 to +0

                // Skirt fallback: handles rays that pass below the triangulated surface
                // (e.g. horizontal rays through the gap between tiles at different zoom levels).
                const hitPos = vec3.scaleAndAdd([], p, d, t);
                const fracx = (hitPos[0] - boundsMin[0]) / (boundsMax[0] - boundsMin[0]);
                const fracy = (hitPos[1] - boundsMin[1]) / (boundsMax[1] - boundsMin[1]);
                const az = sampleElevation(minxUv, minyUv, this.dem) * exaggeration;
                const bz = sampleElevation(maxxUv, minyUv, this.dem) * exaggeration;
                const cz = sampleElevation(maxxUv, maxyUv, this.dem) * exaggeration;
                const dz = sampleElevation(minxUv, maxyUv, this.dem) * exaggeration;
                if (bilinearLerp(az, bz, dz, cz, fracx, fracy) >= hitPos[2])
                    return t;

                continue;
            }

            // Perform intersection tests agains each of the 4 child nodes and store results from closest to furthest.
            let hitCount = 0;

            for (let i = 0; i < this._siblingOffset.length; i++) {

                const childNodeX = (nodex << 1) + this._siblingOffset[i][0];
                const childNodeY = (nodey << 1) + this._siblingOffset[i][1];

                // Decode node aabb from the morton code
                decodeBounds(childNodeX, childNodeY, depth + 1, rootMinx, rootMiny, rootMaxx, rootMaxy, boundsMin, boundsMax);

                boundsMin[2] = -aabbSkirtPadding;
                boundsMax[2] = this.maximums[this.childOffsets[idx] + i] * exaggeration;

                const result = aabbRayIntersect(boundsMin, boundsMax, p, d);
                if (result != null) {
                    // Build the result list from furthest to closest hit.
                    // The order will be inversed when building the stack
                    const tHit: number = result;
                    tHits[i] = tHit;

                    let added = false;
                    for (let j = 0; j < hitCount && !added; j++) {
                        if (tHit >= tHits[sortedHits[j]]) {
                            sortedHits.splice(j, 0, i);
                            added = true;
                        }
                    }
                    if (!added)
                        sortedHits[hitCount] = i;
                    hitCount++;
                }
            }

            // Continue recursion from closest to furthest
            for (let i = 0; i < hitCount; i++) {
                const hitIdx = sortedHits[i];
                stack.push({
                    idx: this.childOffsets[idx] + hitIdx,
                    t: tHits[hitIdx],
                    nodex: (nodex << 1) + this._siblingOffset[hitIdx][0],
                    nodey: (nodey << 1) + this._siblingOffset[hitIdx][1],
                    depth: depth + 1
                });
            }
        }

        return null;
    }

    _addNode(min: number, max: number, leaf: number): number {
        this.minimums.push(min);
        this.maximums.push(max);
        this.leaves.push(leaf);
        this.childOffsets.push(0);
        return this.nodeCount++;
    }

    _construct(mips: Array<MipLevel>, x: number, y: number, lvl: number, parentIdx: number) {
        if (mips[lvl].isLeaf(x, y) === 1) {
            return;
        }

        // Update parent offset
        if (!this.childOffsets[parentIdx])
            this.childOffsets[parentIdx] = this.nodeCount;

        // Construct all 4 children and place them next to each other in memory
        const childLvl = lvl - 1;
        const childMip = mips[childLvl];

        let leafMask = 0;
        let firstNodeIdx = 0;

        for (let i = 0; i < this._siblingOffset.length; i++) {
            const childX = x * 2 + this._siblingOffset[i][0];
            const childY = y * 2 + this._siblingOffset[i][1];

            const elevation = childMip.getElevation(childX, childY);
            const leaf = childMip.isLeaf(childX, childY);
            const nodeIdx = this._addNode(elevation.min, elevation.max, leaf);

            if (leaf)
                leafMask |= 1 << i;
            if (!firstNodeIdx)
                firstNodeIdx = nodeIdx;
        }

        // Continue construction of the tree recursively to non-leaf nodes.
        for (let i = 0; i < this._siblingOffset.length; i++) {
            if (!(leafMask & (1 << i))) {
                this._construct(mips, x * 2 + this._siblingOffset[i][0], y * 2 + this._siblingOffset[i][1], childLvl, firstNodeIdx + i);
            }
        }
    }
}

function bilinearLerp(p00: number, p10: number, p01: number, p11: number, x: number, y: number): number {
    return interpolate(
        interpolate(p00, p01, y),
        interpolate(p10, p11, y),
        x
    );
}

// Sample elevation in normalized uv-space ([0, 0] is the top left)
// This function does not account for exaggeration
export function sampleElevation(fx: number, fy: number, dem: DEMData): number {
    // Sample position in texels
    const demSize = dem.dim;
    const x = clamp(fx * demSize - 0.5, 0, demSize - 1);
    const y = clamp(fy * demSize - 0.5, 0, demSize - 1);

    // Compute 4 corner points for bilinear interpolation
    const ixMin = Math.floor(x);
    const iyMin = Math.floor(y);
    const ixMax = Math.min(ixMin + 1, demSize - 1);
    const iyMax = Math.min(iyMin + 1, demSize - 1);

    const e00 = dem.get(ixMin, iyMin);
    const e10 = dem.get(ixMax, iyMin);
    const e01 = dem.get(ixMin, iyMax);
    const e11 = dem.get(ixMax, iyMax);

    return bilinearLerp(e00, e10, e01, e11, x - ixMin, y - iyMin);
}

export function buildDemMipmap(dem: DEMData): Array<MipLevel> {
    const demSize = dem.dim;

    const elevationDiffThreshold = 5;
    const texelSizeOfMip0 = 8;
    const levelCount = Math.ceil(Math.log2(demSize / texelSizeOfMip0));
    const mips: Array<MipLevel> = [];

    let blockCount = Math.ceil(Math.pow(2, levelCount));

    const blockSamples = (x: number, y: number, size: number, exclusive: boolean, outBounds: Array<number>) => {
        const padding = exclusive ? 1 : 0;
        const minx = x * size;
        const maxx = (x + 1) * size - padding;
        const miny = y * size;
        const maxy = (y + 1) * size - padding;

        outBounds[0] = minx;
        outBounds[1] = miny;
        outBounds[2] = maxx;
        outBounds[3] = maxy;
    };

    // Mip 0: use bilinear corner samples for MIN (preserves existing behaviour for
    // getMinElevationBelowMSL and the rendering pipeline) but scan all raw DEM texels
    // for MAX. The corner approach underestimates peaks between samples, so the AABB
    // z-max was too low — causing the DDA to start at the wrong cell and miss hits.
    let mip = new MipLevel(blockCount);
    const blockSize = 1 / blockCount;
    const {floatView, stride} = dem;
    const blockBounds: number[] = [];

    for (let idx = 0; idx < blockCount * blockCount; idx++) {
        const by = Math.floor(idx / blockCount);
        const bx = idx % blockCount;

        // MIN: bilinear at the 4 corners (unchanged from original)

        blockSamples(bx, by, blockSize, false, blockBounds);

        const e0 = sampleElevation(blockBounds[0], blockBounds[1], dem);

        const e1 = sampleElevation(blockBounds[2], blockBounds[1], dem);

        const e2 = sampleElevation(blockBounds[2], blockBounds[3], dem);

        const e3 = sampleElevation(blockBounds[0], blockBounds[3], dem);
        const blockMin = Math.min(e0, e1, e2, e3);

        // MAX: scan all raw texels (plus one border texel per edge) for true peak detection
        const txStart = Math.max(0, bx * texelSizeOfMip0 - 1);
        const txEnd   = Math.min(demSize - 1, (bx + 1) * texelSizeOfMip0);
        const tyStart = Math.max(0, by * texelSizeOfMip0 - 1);
        const tyEnd   = Math.min(demSize - 1, (by + 1) * texelSizeOfMip0);
        let blockMax = -Infinity;
        for (let ty = tyStart; ty <= tyEnd; ty++) {
            const rowBase = (ty + 1) * stride;
            for (let tx = txStart; tx <= txEnd; tx++) {
                const v = floatView[rowBase + tx + 1];
                if (v > blockMax) blockMax = v;
            }
        }

        mip.minimums.push(blockMin);
        mip.maximums.push(blockMax);
        mip.leaves.push(1);
    }

    mips.push(mip);

    // Construct the rest of the mip levels from bottom to up
    for (blockCount /= 2; blockCount >= 1; blockCount /= 2) {
        const prevMip = mips.at(-1);

        mip = new MipLevel(blockCount);

        for (let idx = 0; idx < blockCount * blockCount; idx++) {
            const y = Math.floor(idx / blockCount);
            const x = idx % blockCount;

            // Sample elevation of all 4 children mip texels. 4 leaf nodes can be concatenated into a single
            // leaf if the total elevation difference is below the threshold value

            blockSamples(x, y, 2, true, blockBounds);

            const e0 = prevMip.getElevation(blockBounds[0], blockBounds[1]);

            const e1 = prevMip.getElevation(blockBounds[2], blockBounds[1]);

            const e2 = prevMip.getElevation(blockBounds[2], blockBounds[3]);

            const e3 = prevMip.getElevation(blockBounds[0], blockBounds[3]);

            const l0 = prevMip.isLeaf(blockBounds[0], blockBounds[1]);

            const l1 = prevMip.isLeaf(blockBounds[2], blockBounds[1]);

            const l2 = prevMip.isLeaf(blockBounds[2], blockBounds[3]);

            const l3 = prevMip.isLeaf(blockBounds[0], blockBounds[3]);

            const minElevation = Math.min(e0.min, e1.min, e2.min, e3.min);
            const maxElevation = Math.max(e0.max, e1.max, e2.max, e3.max);
            const canConcatenate = l0 && l1 && l2 && l3;

            mip.maximums.push(maxElevation);
            mip.minimums.push(minElevation);

            if (maxElevation - minElevation <= elevationDiffThreshold && canConcatenate) {
                // All samples have uniform elevation. Mark this as a leaf
                mip.leaves.push(1);
            } else {
                mip.leaves.push(0);
            }
        }

        mips.push(mip);
    }

    return mips;
}
import {Float32Image} from '../util/image';
import {warnOnce, clamp} from '../util/util';
import {register} from '../util/web_worker_transfer';
import DemMinMaxQuadTree from './dem_tree';
import assert from '../style-spec/util/assert';
import browser from '../util/browser';

import type {CanonicalTileID} from '../source/tile_id';
import type {RGBAImage} from '../util/image';

export type DEMSourceEncoding = 'mapbox' | 'terrarium';

// DEMData is a data structure for decoding, backfilling, and storing elevation data for processing in the hillshade shaders
// data can be populated either from a pngraw image tile or from serliazed data sent back from a worker. When data is initially
// loaded from a image tile, we decode the pixel values using the appropriate decoding formula, but we store the
// elevation data as an Int32 value. we add 65536 (2^16) to eliminate negative values and enable the use of
// integer overflow when creating the texture used in the hillshadePrepare step.

// DEMData also handles the backfilling of data from a tile's neighboring tiles. This is necessary because we use a pixel's 8
// surrounding pixel values to compute the slope at that pixel, and we cannot accurately calculate the slope at pixels on a
// tile's edge without backfilling from neighboring tiles.

const unpackVectors = {
    mapbox: [6553.6, 25.6, 0.1, 10000.0],
    terrarium: [256.0, 1.0, 1.0 / 256.0, 32768.0]
} as const;

function unpackMapbox(r: number, g: number, b: number): number {
    // unpacking formula for mapbox.terrain-rgb:
    // https://www.mapbox.com/help/access-elevation-data/#mapbox-terrain-rgb
    return ((r * 256 * 256 + g * 256.0 + b) / 10.0 - 10000.0);
}

function unpackTerrarium(r: number, g: number, b: number): number {
    // unpacking formula for mapzen terrarium:
    // https://aws.amazon.com/public-datasets/terrain/
    return ((r * 256 + g + b / 256) - 32768.0);
}

export default class DEMData {
    uid: number;
    stride!: number;
    dim!: number;
    borderReady!: boolean;
    _tree!: DemMinMaxQuadTree;
    _modifiedForSources!: {
        [key: string]: Array<CanonicalTileID>;
    };
    _timestamp!: number;
    pixels!: Uint8Array;
    floatView!: Float32Array;
    get tree(): DemMinMaxQuadTree {
        if (!this._tree) this._buildQuadTree();
        return this._tree;
    }

    // RGBAImage data has uniform 1px padding on all sides: square tile edge size defines stride
    // and dim is calculated as stride - 2.
    constructor(
        uid: number,
        data: ImageData,
        sourceEncoding: DEMSourceEncoding,
        borderReady: boolean = false,
    ) {
        // debugger;
        this.uid = uid;
        if (data.height !== data.width) throw new RangeError('DEM tiles must be square');
        if (sourceEncoding && sourceEncoding !== "mapbox" && sourceEncoding !== "terrarium") {
            warnOnce(`"${sourceEncoding}" is not a valid encoding type. Valid types include "mapbox" and "terrarium".`);
            return;
        }

        this.stride = data.height;
        const dim = this.dim = data.height - 2;
        const values = new Uint32Array(data.data.buffer);
        this.pixels = new Uint8Array(data.data.buffer);
        this.floatView = new Float32Array(data.data.buffer);
        this.borderReady = borderReady;
        this._modifiedForSources = {};

        if (!borderReady) {
            // in order to avoid flashing seams between tiles, here we are initially populating a 1px border of pixels around the image
            // with the data of the nearest pixel from the image. this data is eventually replaced when the tile's neighboring
            // tiles are loaded and the accurate data can be backfilled using DEMData#backfillBorder
            for (let x = 0; x < dim; x++) {
                // left vertical border
                values[this._idx(-1, x)] = values[this._idx(0, x)];
                // right vertical border
                values[this._idx(dim, x)] = values[this._idx(dim - 1, x)];
                // left horizontal border
                values[this._idx(x, -1)] = values[this._idx(x, 0)];
                // right horizontal border
                values[this._idx(x, dim)] = values[this._idx(x, dim - 1)];
            }
            // corners
            values[this._idx(-1, -1)] = values[this._idx(0, 0)];
            values[this._idx(dim, -1)] = values[this._idx(dim - 1, 0)];
            values[this._idx(-1, dim)] = values[this._idx(0, dim - 1)];
            values[this._idx(dim, dim)] = values[this._idx(dim - 1, dim - 1)];
