        errors = errors.concat(validateArray({
            key: options.key,
            value,
            valueSpec: options.valueSpec as ArraySpec,
            style: options.style,
            styleSpec: options.styleSpec,
            arrayElementValidator: validateFunctionStop as (...args: unknown[]) => ValidationError[]
