const APPEARANCES_DISALLOWED_PARAMETERS = new Set([
    'zoom', 'pitch', 'distance-from-center',
    'feature', 'feature-state',
    'measure-light',
    'heatmap-density', 'line-progress',
    'raster-value', 'raster-particle-speed', 'sky-radial-progress',
