    const errors: ValidationError[] = [];

    if (e instanceof CompoundExpression) {
        const param = FEATURE_OPERATORS.has(e.name) ? 'feature' : e.name;
        if (APPEARANCES_DISALLOWED_PARAMETERS.has(param)) {
