let properties: Properties<LightProps>;
export const getProperties = (): Properties<LightProps> => properties || (properties = new Properties({
    "direction": new DirectionProperty(styleSpec["properties_light_directional"]["direction"]),
    "color": new DataConstantProperty(styleSpec["properties_light_directional"]["color"]),
    "color-use-theme": new DataConstantProperty({"type":"string","default":"default","property-type":"data-constant"}),
    "intensity": new DataConstantProperty(styleSpec["properties_light_directional"]["intensity"]),
    "cast-shadows": new DataConstantProperty(styleSpec["properties_light_directional"]["cast-shadows"]),
    "shadow-quality": new DataConstantProperty(styleSpec["properties_light_directional"]["shadow-quality"]),
    "shadow-intensity": new DataConstantProperty(styleSpec["properties_light_directional"]["shadow-intensity"]),
    "shadow-draw-before-layer": new DataConstantProperty(styleSpec["properties_light_directional"]["shadow-draw-before-layer"]),
}));
import {Uniform1f, Uniform3f, UniformMatrix4f} from '../../../src/render/uniform_binding';

import type Context from '../../../src/gl/context';
import type {mat4} from 'gl-matrix';
import type {UniformValues} from '../../../src/render/uniform_binding';

export type BuildingUniformsType = {
    ['u_matrix']: UniformMatrix4f;
    ['u_normal_matrix']: UniformMatrix4f;
    ['u_opacity']: Uniform1f;
    ['u_faux_facade_ao_intensity']: Uniform1f;
    ['u_camera_pos']: Uniform3f;
    ['u_tile_to_meter']: Uniform1f;
    ['u_facade_emissive_chance']: Uniform1f;
    ['u_flood_light_color']: Uniform3f;
    ['u_flood_light_intensity']: Uniform1f;
    ['u_front_cutoff_params']: Uniform3f;
};

export type BuildingDefinesType = 'DEBUG_SHOW_NORMALS' | 'HAS_ATTRIBUTE_a_part_color_emissive' | 'HAS_ATTRIBUTE_a_bloom_attenuation' | 'BUILDING_FAUX_FACADE' | 'HAS_ATTRIBUTE_a_faux_facade_color_emissive' | 'RENDER_FRONT_CUTOFF';

const buildingUniforms = (context: Context): BuildingUniformsType => ({
    'u_matrix': new UniformMatrix4f(context),
    'u_normal_matrix': new UniformMatrix4f(context),
    'u_opacity': new Uniform1f(context),
    'u_faux_facade_ao_intensity': new Uniform1f(context),
    'u_camera_pos': new Uniform3f(context),
    'u_tile_to_meter': new Uniform1f(context),
    'u_facade_emissive_chance': new Uniform1f(context),
    'u_flood_light_color': new Uniform3f(context),
    'u_flood_light_intensity': new Uniform1f(context),
    'u_front_cutoff_params': new Uniform3f(context),
});

const buildingUniformValues = (matrix: mat4, normalMatrix: mat4, opacity: number, aoIntensity: number, cameraPos: [number, number, number], tileToMeter: number, emissiveChance: number, floodLightColor: [number, number, number], floodLightIntensity: number, frontCutoffParams: [number, number, number] = [0, 0, 1]): UniformValues<BuildingUniformsType> => {
    const uniformValues = {
        'u_matrix': matrix as Float32Array,
        'u_normal_matrix': normalMatrix as Float32Array,
        'u_opacity': opacity,
        'u_faux_facade_ao_intensity': aoIntensity,
        'u_camera_pos': cameraPos,
        'u_tile_to_meter': tileToMeter,
        'u_facade_emissive_chance': emissiveChance,
        'u_flood_light_color': floodLightColor,
        'u_flood_light_intensity': floodLightIntensity,
        'u_front_cutoff_params': frontCutoffParams,
    };

    return uniformValues;
};

export type BuildingBloomUniformsType = {
    ['u_matrix']: UniformMatrix4f;
};

const buildingBloomUniforms = (context: Context): BuildingBloomUniformsType => ({
    'u_matrix': new UniformMatrix4f(context),
});

const buildingBloomUniformValues = (matrix: mat4): UniformValues<BuildingBloomUniformsType> => {
    const uniformValues = {
        'u_matrix': matrix as Float32Array,
    };

    return uniformValues;
};

export type BuildingDepthUniformsType = {
    ['u_matrix']: UniformMatrix4f;
};

const buildingDepthUniforms = (context: Context): BuildingDepthUniformsType => ({
    'u_matrix': new UniformMatrix4f(context),
});

const buildingDepthUniformValues = (matrix: mat4): UniformValues<BuildingDepthUniformsType> => {
    const uniformValues = {
        'u_matrix': matrix as Float32Array,
    };

    return uniformValues;
};

