highp vec2 unpack_pos_from_rgba(highp vec4 v) {
	v = floor(v * 255.0 + 0.5) / 255.0;
	highp vec2 p = vec2(v.x + (v.y / 255.0), v.z + (v.w / 255.0));
    return u_particle_pos_scale * p - u_particle_pos_offset;
}
