// to [MouseEvent](https://developer.mozilla.org/en-US/docs/Web/API/MouseEvent) instance properties
const MODIFIER_KEYS = {
    'Control': 'ctrlKey',
    'Alt': 'altKey',
    'Shift': 'shiftKey',
    'Meta': 'metaKey'
} as const;

